<script>
document.addEventListener('DOMContentLoaded',()=>{const locations=@json($locations),thanas=@json($thanas),division=document.getElementById('division'),district=document.getElementById('district'),thana=document.getElementById('thana'),group=document.getElementById('bloodGroup'),form=document.getElementById('blood-finder'),section=document.getElementById('search-results'),results=document.getElementById('donorResults'),status=document.getElementById('resultStatus');const fill=(s,items,label)=>{s.innerHTML='<option value="">'+label+'</option>';items.forEach(x=>s.add(new Option(x,x)));s.disabled=!items.length};division.onchange=()=>{fill(district,division.value?locations[division.value]:[],'All Districts');fill(thana,[],'All Thanas')};district.onchange=()=>fill(thana,district.value?(thanas[district.value]||[district.value+' Sadar']):[],'All Thanas');document.querySelectorAll('[data-group]').forEach(a=>a.onclick=()=>group.value=a.dataset.group);form.onsubmit=async e=>{e.preventDefault();section.hidden=false;results.innerHTML='<div class="no-results">Searching donors...</div>';section.scrollIntoView({behavior:'smooth'});const q=new URLSearchParams({division:division.value,district:district.value,thana:thana.value,blood_group:group.value});try{const r=await fetch('{{ route('donors.search') }}?'+q,{headers:{Accept:'application/json'}}),data=await r.json();status.textContent=data.length+' available donor(s) found';results.innerHTML=data.length?'':'<div class="no-results">No donor found. Try another nearby location or blood group.</div>';data.forEach(d=>{const c=document.createElement('article');c.className='result-card';c.innerHTML='<span class="group"></span><h3></h3><p class="place"></p><p class="date"></p><a class="phone"></a><br><a class="email"></a>';c.querySelector('.group').textContent=d.blood_group;c.querySelector('h3').textContent=d.name;c.querySelector('.place').textContent='⌖ '+(d.address||d.district||'Bangladesh');c.querySelector('.date').textContent='Last donation: '+(d.last_donation_date||'Not recorded');let p=c.querySelector('.phone');p.textContent=d.phone?'☎ '+d.phone:'Phone not provided';if(d.phone)p.href='tel:'+d.phone;let m=c.querySelector('.email');m.textContent='✉ '+d.email;m.href='mailto:'+d.email;results.appendChild(c)})}catch(x){status.textContent='Search unavailable';results.innerHTML='<div class="no-results">Could not load donors. Please try again.</div>'}};document.getElementById('closeResults').onclick=()=>{section.hidden=true;form.reset();fill(district,[],'All Districts');fill(thana,[],'All Thanas')}});
</script>
